608:   function createRoad(waypoints, width = 8) {
609:     const pts = [];
610:     for (let i = 0; i < waypoints.length - 1; i++) {
611:       const a = waypoints[i];
612:       const b = waypoints[i + 1];
613:       const segLen = Math.hypot(b.x - a.x, b.z - a.z);
614:       const steps = Math.max(1, Math.ceil(segLen / 2.5));
615:       for (let s = 0; s < steps; s++) {
616:         const t = s / steps;
617:         pts.push({ x: a.x + (b.x - a.x) * t, z: a.z + (b.z - a.z) * t });
618:       }
619:     }
620:     pts.push(waypoints[waypoints.length - 1]);
621: 
622:     const positions = [];
623:     const uvs = [];
624:     const indices = [];
625:     let run = 0;
626:     const half = width / 2;
627: 
628:     for (let i = 0; i < pts.length; i++) {
629:       const p = pts[i];
630:       const prev = pts[Math.max(0, i - 1)];
631:       const next = pts[Math.min(pts.length - 1, i + 1)];
632:       let dx = next.x - prev.x;
633:       let dz = next.z - prev.z;
634:       const len = Math.hypot(dx, dz) || 1;
635:       dx /= len;
636:       dz /= len;
637:       const nx = -dz;
638:       const nz = dx;
639:       if (i > 0) run += Math.hypot(p.x - pts[i - 1].x, p.z - pts[i - 1].z);
640:       const y = terrainHeight(p.x, p.z) + 0.07;
641:       positions.push(p.x + nx * half, y, p.z + nz * half);
642:       positions.push(p.x - nx * half, y, p.z - nz * half);
643:       uvs.push(0, run / 9, 1, run / 9);
644:       if (i > 0) {
645:         const k = i * 2;
646:         indices.push(k - 2, k - 1, k, k - 1, k + 1, k);
647:       }
648:     }
649: 
650:     const geo = new THREE.BufferGeometry();
651:     geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
652:     geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
653:     geo.setIndex(indices);
654:     geo.computeVertexNormals();
655: 
656:     const mesh = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({
657:       map: roadTex,
658:       roughness: 0.98,
659:       metalness: 0.02,
660:       polygonOffset: true,
661:       polygonOffsetFactor: -2,
662:       side: THREE.DoubleSide,
663:     }));
664:     mesh.receiveShadow = true;
665:     scene.add(mesh);
666:     return mesh;
667:   }
