175: // Extrudes a side-on (z/y) silhouette across the weapon's width, which gives
176: // stocks and grips a shaped profile instead of reading as stacked boxes.
177: function addProfile(group, points, thickness, mat, x = 0) {
178:   const shape = new THREE.Shape();
179:   points.forEach(([z, y], i) => {
180:     if (i === 0) shape.moveTo(z, y);
181:     else shape.lineTo(z, y);
182:   });
183:   shape.closePath();
184: 
185:   const bevel = 0.004;
186:   const geo = new THREE.ExtrudeGeometry(shape, {
187:     depth: thickness - bevel * 2,
188:     bevelEnabled: true,
189:     bevelSegments: 2,
190:     steps: 1,
191:     bevelSize: bevel,
192:     bevelThickness: bevel,
193:     curveSegments: 2,
194:   });
195:   geo.translate(0, 0, -(thickness - bevel * 2) / 2);
196:   geo.rotateY(-Math.PI / 2);
197: 
198:   const mesh = new THREE.Mesh(geo, mat);
199:   mesh.position.x = x;
200:   group.add(mesh);
201:   return mesh;
202: }
