350: let sharedFlashTexture = null;
351: 
352: function flashTexture() {
353:   if (sharedFlashTexture) return sharedFlashTexture;
354:   const c = document.createElement('canvas');
355:   c.width = c.height = 128;
356:   const ctx = c.getContext('2d');
357:   const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
358:   g.addColorStop(0, 'rgba(255,255,240,1)');
359:   g.addColorStop(0.25, 'rgba(255,210,130,0.95)');
360:   g.addColorStop(0.55, 'rgba(255,120,30,0.5)');
361:   g.addColorStop(1, 'rgba(255,80,0,0)');
362:   ctx.fillStyle = g;
363:   ctx.fillRect(0, 0, 128, 128);
364:   const tex = new THREE.CanvasTexture(c);
365:   tex.colorSpace = THREE.SRGBColorSpace;
366:   sharedFlashTexture = tex;
367:   return tex;
368: }
