370: function addMuzzleFlash(group, z, scale = 0.5) {
371:   const flash = new THREE.Sprite(new THREE.SpriteMaterial({
372:     map: flashTexture(),
373:     blending: THREE.AdditiveBlending,
374:     depthWrite: false,
375:     transparent: true,
376:     toneMapped: false,
377:   }));
378:   flash.position.set(0, 0.018, z);
379:   flash.scale.setScalar(scale);
380:   flash.visible = false;
381:   group.add(flash);
382: 
383:   const flashLight = new THREE.PointLight(0xffb060, 0, 14, 2);
384:   flashLight.position.set(0, 0.02, z + 0.05);
385:   group.add(flashLight);
386: 
387:   return { flash, flashLight };
388: }
