const DEADZONE = 0.16;
const TRIGGER = 0.28;

const BTN = {
  A:0, B:1, X:2, Y:3, LB:4, RB:5, LT:6, RT:7, BACK:8, START:9, L3:10, R3:11,
  UP:12, DOWN:13, LEFT:14, RIGHT:15
};

function dz(value, deadzone=DEADZONE) {
  const a = Math.abs(value);
  if (a <= deadzone) return 0;
  const scaled = (a - deadzone) / (1 - deadzone);
  return Math.sign(value) * scaled;
}
function curve(v, exp=1.45) { return Math.sign(v) * Math.pow(Math.abs(v), exp); }
```

