handleGamepad() {
  const pad = this.gamepad;
  if (!pad.connected) return;

  // The field manual is a DOM overlay; controller Start/Back dismisses it.
  const helpOpen = !!(this.isHelpOpen && this.isHelpOpen());
  if (helpOpen) {
    if (pad.start || pad.back) this.closeHelp?.();
    return;
  }

  if (pad.help) {
    if (this.state === 'playing') {
      this.pause();
      this.openHelp?.('pause');
    } else if (this.state === 'paused') {
      this.openHelp?.('pause');
    } else if (this.state === 'menu') {
      this.openHelp?.('start');
    }
    return;
  }

  if (pad.pause && this.state === 'playing') {
    this.pause();
    return;
  }

  if (pad.start) {
    if (this.state === 'menu') {
      this.startRun();
      pad.consume('jump');
      pad.consume('start');
      return;
    }
    if (this.state === 'paused') {
      this.resume();
      pad.consume('start');
      return;
    }
    if ((this.state === 'dead' || this.state === 'extracted') && performance.now() - this.endAt > 800) {
      this.startRun();
      pad.consume('jump');
      pad.consume('start');
      return;
    }
  }

  if (this.state !== 'playing') return;

  if (pad.reload) this.player.reload();
  if (pad.nextWeapon) this.player.cycleWeapon();
  if (pad.prevWeapon) {
    const count = this.player.weapons.length;
    this.player.switchWeapon((this.player.weaponIndex + count - 1) % count);
  }
}

